/** A synthetic create endpoint that echoes the submitted manifest, then admits each staged upload in turn; `hold` delays the create answer. */
function createServer(hold?: Promise<void>) {
  const created: Record<string, any>[] = [], uploads: string[] = []; let item = detail(), active = 0, max = 0;
  stubFetch(vi.fn(async (path: string, init: RequestInit) => {
    if (init.method === 'POST' && path.endsWith('/imports')) {
      const body = JSON.parse(String(init.body)); created.push(body); await hold;
      item = { ...detail(), manifest: body.manifest, suggestions: [], capabilities: { analysis: true, upload: true, publish: false }, upload: { ready: 0, total: body.manifest.files.length, available: true }, publication: 'notStarted',
        draft: { album: detail().draft.album, tracks: body.manifest.files.map((file: { slotId: string }) => ({ slotId: file.slotId, title: '', discNumber: null, trackNumber: null })) } };
      return json({ item, receipt: { kind: 'create', revision: 1, operationId: body.operationId } }, 201);
    }
    if (init.method === 'POST' && path.includes('/assets/')) {
      active++; max = Math.max(max, active); uploads.push(path); await new Promise(resolve => setTimeout(resolve, 2));
      const slot = path.split('/').at(-1)!, operationId = new Headers(init.headers).get('Idempotency-Key')!;
      item = { ...item, revision: item.revision + 1, assets: [...item.assets, { slotId: slot, state: 'ready', byteLength: 15, sha256: 'a'.repeat(64), contentType: 'audio/mpeg', tags: null, recovery: { operationId, expectedRevision: Number(new Headers(init.headers).get('If-Match')), kind: 'upload', startedByMe: true } }] };
      active--; return json({ item, receipt: { operationId, kind: 'upload', revision: item.revision } });
    }
    return json({ item, receipt: null });
  }));
  return { created, uploads, max: () => max };
}
