test('after a stale approval the page reloads the saved project, and approving again sends its new digest with the same unsaved edit', async () => {
  const server = fieldSaveEndpoint(decidedProject()), publishes: Record<string, any>[] = [], newer = 'f'.repeat(64); let reads = 0;
  stubFetch(vi.fn(async (path: string, init?: RequestInit) => {
    if (path === `/api/admin/v1/imports/${projectId}` && !init?.method) reads++;
    if (init?.method !== 'POST' || !path.endsWith('/publish')) return server.fetch(path, init);
    const body = JSON.parse(String(init.body)), current = server.current(); publishes.push(body);
    // Automation changed a shown value without a new revision, so an approval built on the earlier digest is stale.
    if (body.approvalDigest !== newer) { server.set({ ...current, approvalDigest: newer }); return json({ code: 'ADMIN_IMPORT_APPROVAL_STALE' }, 409); }
    server.set({ ...current, revision: current.revision + 1, draft: applyDraftChanges(current.draft, body.changes), publication: 'preparing' });
    return json({ item: server.current(), receipt: { operationId: body.operationId, kind: 'publish', revision: server.current().revision } }, 202);
  }));
  mount(`/admin/imports/${projectId}`);
  fireEvent.change(await screen.findByRole('textbox', { name: 'Title' }), { target: { value: 'Approved Title' } });
  const approve = async () => {
    fireEvent.click(screen.getByRole('tab', { name: 'Publish' })); fireEvent.click(await screen.findByRole('button', { name: 'Publish Album' }));
    const button = within(screen.getByRole('dialog')).getByRole('button', { name: 'Publish Album' }); await waitFor(() => expect(button).toBeEnabled()); fireEvent.click(button);
  };
  await approve(); const readsAfterRefusal = reads;
  expect(await screen.findByText(changedElsewhere)).toBeVisible(); await waitFor(() => expect(reads).toBeGreaterThan(readsAfterRefusal));
  await waitFor(() => expect(screen.getByRole('button', { name: 'Publish Album' })).toBeEnabled()); await approve();
  await waitFor(() => expect(publishes).toHaveLength(2));
  const change = [{ path: 'album.title', base: 'Synthetic Album', value: 'Approved Title' }];
  expect(publishes.map(body => [body.expectedRevision, body.changes, body.approvalDigest])).toEqual([[3, change, 'e'.repeat(64)], [3, change, newer]]);
  expect(publishes[1].operationId).not.toBe(publishes[0].operationId);
  fireEvent.click(screen.getByRole('tab', { name: 'Draft' }));
  await waitFor(() => expect(screen.getByRole('textbox', { name: 'Title' })).toHaveValue('Approved Title')); await waitFor(() => expect(screen.getByRole('button', { name: 'Save' })).toBeDisabled());
  expect(server.writes).toEqual([]);
});

